Here's a complete example:

**XAML (ItemsPage.xaml)**
```xml
<ContentPage xmlns="http://schemas.microsoft.com/dotnet/2021/maui"
             xmlns:x="http://schemas.microsoft.com/winfx/2009/xaml"
             x:Class="MyApp.Views.ItemsPage">

    <CollectionView ItemsSource="{Binding Items}"
                    SelectionMode="Single"
                    SelectedItem="{Binding SelectedItem}"
                    IsRefreshing="{Binding IsRefreshing}"
                    RemainingItemsThreshold="0">

        <CollectionView.Header>
            <RefreshView Command="{Binding RefreshCommand}"
                         IsRefreshing="{Binding IsRefreshing}">
                <!-- wrapping won't work; see below -->
            </RefreshView>
        </CollectionView.Header>

    </CollectionView>

</ContentPage>
```

The correct pattern is to **wrap the CollectionView** in a `RefreshView`:

```xml
<ContentPage xmlns="http://schemas.microsoft.com/dotnet/2021/maui"
             xmlns:x="http://schemas.microsoft.com/winfx/2009/xaml"
             x:Class="MyApp.Views.ItemsPage"
             xmlns:vm="clr-namespace:MyApp.ViewModels">

    <ContentPage.BindingContext>
        <vm:ItemsViewModel />
    </ContentPage.BindingContext>

    <RefreshView Command="{Binding RefreshCommand}"
                 IsRefreshing="{Binding IsRefreshing}">

        <CollectionView ItemsSource="{Binding Items}"
                        SelectionMode="Single"
                        SelectedItem="{Binding SelectedItem}">
            <CollectionView.ItemTemplate>
                <DataTemplate>
                    <VerticalStackLayout Padding="12" Spacing="4">
                        <Label Text="{Binding Name}"
                               FontSize="18"
                               FontAttributes="Bold" />
                        <Label Text="{Binding Description}"
                               FontSize="14"
                               TextColor="Gray" />
                    </VerticalStackLayout>
                </DataTemplate>
            </CollectionView.ItemTemplate>
        </CollectionView>

    </RefreshView>
</ContentPage>
```

**ViewModel (ItemsViewModel.cs)**
```csharp
public partial class ItemsViewModel : ObservableObject
{
    private readonly IApiService _api;
    private readonly INavigationService _nav;

    [ObservableProperty]
    private ObservableCollection<Item> _items = new();

    [ObservableProperty]
    private bool _isRefreshing;

    private Item? _selectedItem;
    public Item? SelectedItem
    {
        get => _selectedItem;
        set
        {
            if (SetProperty(ref _selectedItem, value) && value is not null)
            {
                GoToDetailAsync(value);
                SelectedItem = null; // reset so the same item can be re-selected
            }
        }
    }

    public ItemsViewModel(IApiService api, INavigationService nav)
    {
        _api = api;
        _nav = nav;
    }

    [RelayCommand]
    private async Task RefreshAsync()
    {
        try
        {
            var data = await _api.GetItemsAsync();
            Items = new ObservableCollection<Item>(data);
        }
        finally
        {
            IsRefreshing = false; // stops the spinner
        }
    }

    private async void GoToDetailAsync(Item item)
    {
        await Shell.Current.GoToAsync(
            nameof(DetailPage),
            new Dictionary<string, object> { ["Item"] = item });
    }
}
```

**Key binding relationships:**

| XAML Property | ViewModel Property | Purpose |
|---|---|---|
| `ItemsSource` | `Items` (ObservableCollection) | Drives the list |
| `SelectionMode="Single"` | — | Enables tap-to-select |
| `SelectedItem` | `SelectedItem` | Fires setter → navigates, then resets to `null` |
| `RefreshView.Command` | `RefreshCommand` | Generated by `[RelayCommand]` on `RefreshAsync` |
| `RefreshView.IsRefreshing` | `IsRefreshing` | Set `false` when done to dismiss spinner |

**Important details:**
- `RefreshView` wraps `CollectionView` (not inside it) — this is required for pull-to-refresh.
- Reset `SelectedItem` to `null` after navigation so the same row can be tapped again.
- Set `IsRefreshing = false` in a `finally` block to guarantee the spinner stops even on errors.
- Uses **MVVM Community Toolkit** (`[ObservableProperty]`, `[RelayCommand]`) to reduce boilerplate.
